#!/usr/bin/env node
/**
 * Writes the CompactLab design system into every app of the workspace.
 *
 *   node compactlab/design-system/sync.mjs          # write
 *   node compactlab/design-system/sync.mjs --check  # exit 1 if any app drifted
 *
 * Each app is its own repo and deploys on its own, so it gets a committed copy
 * of the generated files rather than a runtime dependency. Apps that are not
 * checked out next to compactlab are skipped.
 */
import { copyFileSync, existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { chart, colors, fonts, product } from "./tokens.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const workspace = join(here, "..", "..");
const check = process.argv.includes("--check");

/** product: true adds the dense type scale and radii (not for marketing pages). */
const APPS = [
  { dir: "compactlab", product: true },
  { dir: "admin", product: true },
  { dir: "landing-page", product: false },
];

const NOTICE = "GENERATED by compactlab/design-system/sync.mjs — do not edit. Change tokens.mjs, then run the sync.";
const CSS_HEADER = `/* ${NOTICE} */\n`;
const TS_HEADER = `// ${NOTICE}\n`;

function tokensCss() {
  const lines = [
    ...Object.entries(colors).map(([k, v]) => `  --color-${k}: ${v};`),
    ...chart.map((v, i) => `  --color-chart-${i + 1}: ${v};`),
    `  --font-sans: ${fonts.sans};`,
    `  --font-mono: ${fonts.mono};`,
  ];
  // static: emit every variable so inline styles can use var(--color-*) too.
  return `${CSS_HEADER}@theme static {\n${lines.join("\n")}\n}\n`;
}

function productCss() {
  const lines = [
    ...Object.entries(product.text).map(([k, v]) => `  --text-${k}: ${v};`),
    ...Object.entries(product.radius).map(([k, v]) => `  --radius-${k}: ${v};`),
    "",
    "  --animate-pulse-slow: pulse-slow 3s cubic-bezier(0.4,0,0.6,1) infinite;",
    "  --animate-fade-in: fade-in 0.2s ease-out;",
    "  --animate-slide-up: slide-up 0.2s ease-out;",
    "",
    "  @keyframes pulse-slow { 0%, 100% { opacity: 1; } 50% { opacity: 0.4; } }",
    "  @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }",
    "  @keyframes slide-up { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }",
  ];
  return `${CSS_HEADER}@theme {\n${lines.join("\n")}\n}\n`;
}

function tokensTs() {
  return (
    TS_HEADER +
    "// For places CSS variables can't reach (chart libraries, canvas, SVG attributes).\n\n" +
    `export const colors = ${JSON.stringify(colors, null, 2)} as const;\n\n` +
    `/** Categorical chart palette, fixed order. Never cycle; fold extras into "Other". */\n` +
    `export const chartPalette = ${JSON.stringify(chart)} as const;\n\n` +
    `export const fonts = ${JSON.stringify(fonts, null, 2)} as const;\n`
  );
}

const brandDir = join(here, "brand");
const brandFiles = readdirSync(brandDir).filter((f) => !f.startsWith("."));

let drift = 0;
let written = 0;

function emit(path, content) {
  const current = existsSync(path) ? readFileSync(path) : null;
  if (current && Buffer.compare(current, content) === 0) return;
  if (check) {
    drift++;
    console.error(`  drift  ${relative(workspace, path)}`);
    return;
  }
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
  written++;
  console.log(`  wrote  ${relative(workspace, path)}`);
}

for (const app of APPS) {
  const root = join(workspace, app.dir);
  if (!existsSync(join(root, "package.json"))) {
    console.log(`  skip   ${app.dir} (not checked out)`);
    continue;
  }
  emit(join(root, "styles", "compactlab-tokens.css"), Buffer.from(tokensCss()));
  if (app.product) emit(join(root, "styles", "compactlab-product.css"), Buffer.from(productCss()));
  emit(join(root, "lib", "design-tokens.ts"), Buffer.from(tokensTs()));
  for (const f of brandFiles) emit(join(root, "public", f), readFileSync(join(brandDir, f)));
}

if (check) {
  if (drift) {
    console.error(`\n${drift} file(s) differ from compactlab/design-system. Run: node compactlab/design-system/sync.mjs`);
    process.exit(1);
  }
  console.log("Design system in sync.");
} else {
  console.log(written ? `\n${written} file(s) updated.` : "Already in sync.");
}
